import type { TranscriptStorage } from "@trigger.dev/sdk/ai"
import type { UIMessage } from "ai"
import { eq } from "drizzle-orm"

import { db } from "@/lib/db"
import { games } from "@/lib/db/schema"

// Worker-side persistence for the chat agent. No Clerk here: the agent runs in
// the Trigger.dev worker, and ownership is enforced by the server actions that
// create the session and mint its token.

// The games row holds the whole conversation as one document, so save writes
// changeset.transcript as-is and ignores the per-message changes.
export const gameTranscriptStorage: TranscriptStorage = {
  async load<TUIMessage extends UIMessage>(
    { chatId }: { chatId: string },
    opts?: { limit?: number; before?: string },
  ) {
    const [game] = await db
      .select({
        messages: games.messages,
        state: games.transcriptState,
        nonFinalIds: games.nonFinalIds,
        lastEventId: games.lastEventId,
        lastInEventId: games.lastInEventId,
      })
      .from(games)
      .where(eq(games.id, chatId))
      .limit(1)

    if (!game) return { messages: [] as TUIMessage[], state: null }

    const cursors = {
      lastOutEventId: game.lastEventId ?? undefined,
      lastInEventId: game.lastInEventId ?? undefined,
    }

    // A paged read returns the transcript only; state is always null.
    if (opts?.limit || opts?.before) {
      let end = game.messages.length
      if (opts.before) {
        const anchor = game.messages.findIndex((m) => m.id === opts.before)
        if (anchor === -1) return { messages: [] as TUIMessage[], state: null, cursors }
        end = anchor
      }
      const start = opts.limit ? Math.max(0, end - opts.limit) : 0
      return {
        messages: game.messages.slice(start, end) as TUIMessage[],
        state: null,
        cursors,
        nextCursor: start > 0 ? game.messages[start].id : undefined,
      }
    }

    return {
      messages: game.messages as TUIMessage[],
      state: game.state ?? null,
      cursors,
      nonFinalIds: game.nonFinalIds,
    }
  },

  // A single UPDATE is atomic, so messages and resume cursors never diverge.
  async save({ chatId }, { transcript, cursors }) {
    await db
      .update(games)
      .set({
        messages: transcript.entries.map((entry) => entry.message),
        nonFinalIds: transcript.entries
          .filter((entry) => !entry.final)
          .map((entry) => entry.message.id),
        transcriptState: transcript.state,
        ...(cursors && {
          lastEventId: cursors.lastOutEventId,
          lastInEventId: cursors.lastInEventId,
        }),
      })
      .where(eq(games.id, chatId))
  },
}

// The frontend resumes the live stream with this token, so it is saved
// separately from the transcript.
export async function saveGameAccessToken({
  id,
  publicAccessToken,
}: {
  id: string
  publicAccessToken: string
}) {
  await db.update(games).set({ publicAccessToken }).where(eq(games.id, id))
}
