import { anthropic } from "@ai-sdk/anthropic"
import { chat } from "@trigger.dev/sdk/ai"
import { streamText } from "ai"

import {
  gameTranscriptStorage,
  saveGameAccessToken,
} from "@/lib/games/chat-store"

export const gameChat = chat.agent({
  id: "game-chat",
  // The games table stays the source of truth for history.
  storage: gameTranscriptStorage,
  // Saved at turn start so a reload mid-answer can still resume the stream.
  onTurnStart: async ({ chatId, chatAccessToken }) => {
    await saveGameAccessToken({
      id: chatId,
      publicAccessToken: chatAccessToken,
    })
  },
  onTurnComplete: async ({ chatId, chatAccessToken }) => {
    await saveGameAccessToken({
      id: chatId,
      publicAccessToken: chatAccessToken,
    })
  },
  run: async ({ messages, signal }) =>
    streamText({
      ...chat.toStreamTextOptions(),
      model: anthropic("claude-sonnet-5-5"),
      messages,
      abortSignal: signal,
    }),
})
