import type { UIMessage } from "ai"
import {
  index,
  jsonb,
  pgTable,
  text,
  timestamp,
  uuid,
} from "drizzle-orm/pg-core"

export const games = pgTable(
  "games",
  {
    id: uuid("id").primaryKey().defaultRandom(),
    orgId: text("org_id").notNull(),
    title: text("title").notNull(),
    messages: jsonb("messages").$type<UIMessage[]>().notNull().default([]),
    publicAccessToken: text("public_access_token"),
    lastEventId: text("last_event_id"),
    lastInEventId: text("last_in_event_id"),
    transcriptState: jsonb("transcript_state").$type<unknown>(),
    nonFinalIds: jsonb("non_final_ids").$type<string[]>().notNull().default([]),
    createdAt: timestamp("created_at").notNull().defaultNow(),
    updatedAt: timestamp("updated_at")
      .notNull()
      .defaultNow()
      .$onUpdate(() => new Date()),
  },
  (table) => [index("games_org_id_idx").on(table.orgId)],
)
